/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create expression to extract date from visit_time timestamp
  auto visit_date = cast<Date>("visit_time"_c);

  // Build the query: group visits by day and calculate metrics
  auto query = select_from<PageVisit>(
      visit_date | as<"visit_date">,
      count() | as<"total_visits">,
      count_distinct("url"_c) | as<"unique_pages">
  ) | group_by(visit_date) 
    | order_by(visit_date) 
    | to<std::vector<DailyTraffic>>;

  // Connect to database and execute query
  return sqlite::connect("test_db.sqlite")
      .and_then(query)
      .value();
}

