  PrimaryKey(U&& _value) noexcept : value_(std::forward<U>(_value)) {}

  template <class U,
            typename std::enable_if<std::is_convertible_v<U, ReflectionType>,
                                    bool>::type = true>
  PrimaryKey(const PrimaryKey<U>& _other) : value_(_other.value()) {}

  ~PrimaryKey() = default;

