  PrimaryKey() : value_(T()) {}

  PrimaryKey(const T& _value) : value_(_value) {}

  PrimaryKey(PrimaryKey&& _other) noexcept = default;

  PrimaryKey(const PrimaryKey& _other) = default;

  template <class U, bool _other_auto_incr>
