    sql << ")";

    // Connect to database, execute update in a transaction, and commit
    auto result = sqlgen::sqlite::connect("test_db.sqlite")
        .and_then([](auto conn) { 
            return sqlgen::begin_transaction(conn); 
        })
        .and_then([&sql](auto transaction) { 
            return sqlgen::exec(transaction, sql.str()); 
        })
        .and_then([](auto transaction) { 
            return sqlgen::commit(transaction); 
        });

    return result.has_value();
}

}  // namespace soft_delete_records
