  // Update to_account: add amount
  // WHERE account_id = to_account_id
  auto update2 = update<Account>(balance_col.set(balance_col + amount))
                 | where(account_id_col == to_account_id);

  auto result2 = update2(*result1);
  if (!result2) {
    rollback(*trans_result);
    return false;
  }

  // Commit transaction
  auto commit_result = commit(*trans_result);
  if (!commit_result) {
    return false;
  }

  return true;
}

