#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Step 1: Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Step 2: Build the SELECT query for the view
  // This corresponds to:
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  auto query = select_from<Sale, "t1">(
      "name"_t2 | as<"product_name">,
      sum("quantity"_t1) | as<"total_quantity">,
      sum("amount"_t1) | as<"total_revenue">
  )
  | inner_join<Product, "t2">("product_id"_t1 == "product_id"_t2)
  | group_by("name"_t2);

  // Step 3: Create the view (using IF NOT EXISTS for SQLite compatibility)
  auto result = (create_as<SalesSummary>(query) | if_not_exists)(conn_result);

  return result.has_value();
}

}  // namespace schema_create_view_sales_summary
