namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  using namespace sqlgen;

  // Build the temporal analysis query
  auto query = select_from<Event>(
    col<"event_id">,
    col<"event_name">,
    day(col<"start_time">) | as<"start_day">,
    month(col<"start_time">) | as<"start_month">,
    year(col<"start_time">) | as<"start_year">,
    hour(col<"start_time">) | as<"start_hour">,
    minute(col<"start_time">) | as<"start_minute">,
    second(col<"start_time">) | as<"start_second">,
    weekday(col<"start_time">) | as<"start_weekday">,
    unixepoch(col<"start_time">) | as<"start_epoch">,
    days_between(col<"start_time">, col<"end_time">) | as<"duration_days">
  )
  | where(col<"end_time">.is_not_null())
  | to<std::vector<TemporalAnalysis>>;

  // Execute: connect -> create table -> insert events -> run query
  auto result = sqlite::connect("test_db.sqlite")
    .and_then(create_table<Event>)
    .and_then(insert(events))
    .and_then(query);

  // Return results or empty vector on error
  if (result) {
    return *result;
  }

  return {};
}

}  // namespace analyze_temporal_data
