```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  using namespace sqlgen;

  // Connect to SQLite database "test_db.sqlite"
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {};
  }

  // Write data to database (automatically creates tables and inserts data)
  auto db = *conn 
    | write(users)
    | write(friendships);

  if (!db) {
    return {};
  }

  // Query for mutual friends using SELF-JOIN
  // This finds pairs of users (u1, u2) who are connected through mutual friends
  // Logic: u1 -> friend (f1.user2_id) -> u2
  // This represents friend-of-friend relationships
  auto query = select_from<User, "u1">(
      col<"username", "u1"> | as<"user1_name">,
      col<"username", "u2"> | as<"user2_name">
    )
    // f1: friendships where u1 is user1_id (u1's friends)
    | inner_join<Friendship, "f1">(col<"user_id", "u1"> == col<"user1_id", "f1">)
    // f2: friendships where u1's friend is user1_id (friends of u1's friends)
    | inner_join<Friendship, "f2">(col<"user2_id", "f1"> == col<"user1_id", "f2">)
    // u2: the user who is a friend-of-friend
    | inner_join<User, "u2">(col<"user2_id", "f2"> == col<"user_id", "u2">)
    // Avoid duplicate pairs (u1, u2) and (u2, u1)
    | where(col<"user_id", "u1"> < col<"user_id", "u2">)
    // Convert to vector of FriendConnection
    | to<std::vector<FriendConnection>>;

  auto result = query(*db);

  if (!result) {
    return {};
  }

  return *result;
}

}  // namespace analyze_social_network
```

