 * It returns a vector of ValidatedProfile structs, where each struct contains the user_id, trimmed_name, trimmed_email, name_length, and email_length.
 * Returns: std::vector<ValidatedProfile>.
 */
std::vector<ValidatedProfile> trim_and_length_validation() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query to select and transform data from UserProfile table
  // - Select user_id as-is
  // - Trim whitespace from name and email fields
  // - Calculate length of trimmed name and email
  auto result = (
    sqlgen::select_from<UserProfile>(
      "user_id"_c,
      sqlgen::trim("name"_c) | sqlgen::as<"trimmed_name">,
      sqlgen::trim("email"_c) | sqlgen::as<"trimmed_email">,
      sqlgen::length(sqlgen::trim("name"_c)) | sqlgen::as<"name_length">,
      sqlgen::length(sqlgen::trim("email"_c)) | sqlgen::as<"email_length">
    ) | sqlgen::to<std::vector<ValidatedProfile>>
  )(conn);

  // Return the result if successful, otherwise return empty vector
  if (result) {
    return *result;
  }

  return std::vector<ValidatedProfile>();
}

