#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }

  // Write items to database
  auto write_result = write(conn_result, items);
  if (!write_result) {
    return {};
  }

  // Define column references
  auto item_id_col = col<"item_id">;
  auto order_id_col = col<"order_id">;
  auto product_id_col = col<"product_id">;
  auto unit_price_col = col<"unit_price">;
  auto quantity_col = col<"quantity">;
  auto discount_rate_col = col<"discount_rate">;
  auto tax_rate_col = col<"tax_rate">;

  // For discount_rate and tax_rate in the result, coalesce NULL to 0.0
  auto discount_rate_val = coalesce(discount_rate_col, 0.0) | as<"discount_rate">;
  auto tax_rate_val = coalesce(tax_rate_col, 0.0) | as<"tax_rate">;

  // Calculate metrics using arithmetic operations
  // gross_total = unit_price * quantity
  auto gross_total = (unit_price_col * quantity_col) | as<"gross_total">;

  // discounted_total = unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)
  auto discounted_total = (unit_price_col * quantity_col * 
                           (1.0 - coalesce(discount_rate_col, 0.0) / 100.0)) 
                           | as<"discounted_total">;

  // final_total = discounted_total * (1 + COALESCE(tax_rate, 0)/100)
  auto final_total = (unit_price_col * quantity_col * 
                     (1.0 - coalesce(discount_rate_col, 0.0) / 100.0) * 
                     (1.0 + coalesce(tax_rate_col, 0.0) / 100.0)) 
                     | as<"final_total">;

  // unit_cost = unit_price * quantity / quantity (which simplifies to unit_price)
  auto unit_cost = (unit_price_col * quantity_col / quantity_col) | as<"unit_cost">;

  // quantity_group = quantity % 10
  auto quantity_group = (quantity_col % 10) | as<"quantity_group">;

  // estimated_profit = unit_price * 0.3
  auto estimated_profit = (unit_price_col * 0.3) | as<"estimated_profit">;

  // Select from OrderItem table with all calculated fields
  auto query = select_from<OrderItem>(
    item_id_col,
    order_id_col,
    product_id_col,
    unit_price_col,
    quantity_col,
    discount_rate_val,
    tax_rate_val,
    gross_total,
    discounted_total,
    final_total,
    unit_cost,
    quantity_group,
    estimated_profit
  ) | to<std::vector<OrderMetrics>>;

  auto metrics_result = query(write_result);

  if (!metrics_result) {
    return {};
  }

  return *metrics_result;
}

}  // namespace calculate_order_metrics
