#ifndef SQLGEN_COL_HPP_
#define SQLGEN_COL_HPP_

#include <chrono>
#include <rfl.hpp>
#include <string>

#include "transpilation/As.hpp"
#include "transpilation/Col.hpp"
#include "transpilation/Condition.hpp"
#include "transpilation/Desc.hpp"
