#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace column_is_null_checks {

struct Profile {
  sqlgen::PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");

  if (!conn_result) {
    return {};
  }

  auto conn = conn_result.value();

  // Filter profiles where bio IS NULL or avatar_url IS NULL
  // This demonstrates filtering rows with missing fields
  auto profiles_result = (read<std::vector<Profile>> | 
                          where("bio"_c.is_null() || "avatar_url"_c.is_null()))(conn);

  if (!profiles_result) {
    return {};
  }

  // Transform Profile objects to Result objects
  std::vector<Result> results;
  for (const auto& profile : profiles_result.value()) {
    results.push_back({
      profile.profile_id.get(),
      profile.display_name
    });
  }

  return results;
}

}  // namespace column_is_null_checks
