#ifndef SQLGEN_JOINS_HPP_
#define SQLGEN_JOINS_HPP_

#include <rfl.hpp>

#include "transpilation/Join.hpp"

namespace sqlgen {

template <rfl::internal::StringLiteral _alias, transpilation::JoinType _how,
          class TableOrQueryType, class ConditionType>
