  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  const auto query =
      select_from<Supplier, "t1">("name"_t1 | as<"supplier_name">,
                                  "name"_t2 | as<"product_name">) |
      full_join<Product, "t2">("supplier_id"_t1 == "supplier_id"_t2) |
      to<std::vector<SupProd>>;

  return sqlite::connect("test_db.sqlite")
      .and_then(query)
      .value();
}

}  // namespace full_join_suppliers_products
```

This implementation:

1. **Connects to the database**: Uses `sqlite::connect("test_db.sqlite")` to connect to the specified SQLite database
2. **Selects columns with aliases**: 
   - `"name"_t1` (supplier name from table alias t1) → aliased as `"supplier_name"`
   - `"name"_t2` (product name from table alias t2) → aliased as `"product_name"`
3. **Performs FULL JOIN**: Uses `full_join<Product, "t2">` to join the Product table with alias "t2" on the condition `"supplier_id"_t1 == "supplier_id"_t2`
4. **Specifies return type**: Uses `to<std::vector<SupProd>>` to convert the query results to the desired container type
5. **Executes and returns**: Chains the operations with `.and_then()` and retrieves the result with `.value()`

The FULL JOIN ensures that all rows from both the Supplier and Product tables are included in the result, with NULL values (represented as `std::optional`) where there's no match.

