      "first_name"_t1,
      "last_name"_t1,
      "salary"_t1
    )
    | right_join<Department, "t2">("department_id"_t1 == "department_id"_t2)
    | to<std::vector<JoinResult>>
    | (*result);

  if (right_result) {
