      const auto extract_result = [](auto&& _vec) -> Result<ToType> {
        if (_vec.size() != 1) {
          return error(
              "Because the type provided to to<...> was not a container, the "
              "query needs to return exactly one result, but it did return " +
              std::to_string(_vec.size()) + " results.");
