struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT p.product_id, p.product_name, p.category, 
  //        SUM(p.price * s.quantity) as total_sales
  // FROM Product p
  // INNER JOIN Sales s ON p.product_id = s.product_id
  // GROUP BY p.product_id, p.product_name, p.category
  // ORDER BY total_sales DESC
  // LIMIT limit_count
  auto query = select_from<Product, "t1">(
    "product_id"_t1,
    "product_name"_t1,
    "category"_t1,
    sum("price"_t1 * "quantity"_t2) | as<"total_sales">
  )
  | inner_join<Sales, "t2">("product_id"_t1 == "product_id"_t2)
  | group_by("product_id"_t1, "product_name"_t1, "category"_t1)
  | order_by("total_sales"_c.desc())
  | limit(limit_count)
  | to<std::vector<TopProduct>>;

  // Execute query and return results
