#ifndef SQLGEN_CREATEAS_HPP_
#define SQLGEN_CREATEAS_HPP_

#include <concepts>
#include <rfl.hpp>
#include <type_traits>

#include "Result.hpp"
#include "dynamic/CreateAs.hpp"
#include "is_connection.hpp"
#include "select_from.hpp"
