namespace update_with_arithmetic {

struct Player {
  sqlgen::PrimaryKey<int> id;
  int score;
};

/**
 * This function demonstrates updating a column with arithmetic.
 * Returns: std::string.
 */
inline std::string update_with_arithmetic() {
    // Create a column reference for the score field
    auto score = sqlgen::col<"score">;

    // Construct an UPDATE query that sets score = score + 10
    auto query = sqlgen::update<Player>(score.set(score + 10));

    // Convert the query to SQL string using SQLite dialect
    return sqlgen::sqlite::to_sql(query);
}

}  // namespace update_with_arithmetic
