namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  // Connect to database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create column references with table aliases
  auto p_project_id = sqlgen::col<"project_id", "p">;
  auto p_name = sqlgen::col<"name", "p">;
  auto t_start_time = sqlgen::col<"start_time", "t">;
  auto t_end_time = sqlgen::col<"end_time", "t">;
  auto t_project_id = sqlgen::col<"project_id", "t">;

  // Build and execute the query
  auto result = (
    sqlgen::select_from<Project, "p">(
      p_project_id,
      p_name,
      sqlgen::day(t_start_time) | sqlgen::as<"day">,
      sqlgen::month(t_start_time) | sqlgen::as<"month">,
      sqlgen::year(t_start_time) | sqlgen::as<"year">,
      sqlgen::hour(t_start_time) | sqlgen::as<"hour">,
      sqlgen::minute(t_start_time) | sqlgen::as<"minute">,
      sqlgen::second(t_start_time) | sqlgen::as<"second">,
      sqlgen::days_between(t_start_time, t_end_time) | sqlgen::as<"duration_days">
    )
    | sqlgen::inner_join<TimeLog, "t">(p_project_id == t_project_id)
    | sqlgen::to<std::vector<TimeMetrics>>
  )(conn);

  // Handle the result
  if (result) {
    return *result;
  }
  return {};
}

}  // namespace project_time_tracking
