  Result<Nothing> actual_insert(
      const std::vector<std::vector<std::optional<std::string>>>& _data,
      sqlite3_stmt* _stmt) const noexcept;

  /// Implements the actual insert.
  Result<Nothing> insert_impl(
      const dynamic::Insert& _stmt,
