#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_table_as_select {

struct Source {
  sqlgen::PrimaryKey<int> id;
  int value;
};

struct Target {
  int value;
};

/**
 * This function demonstrates creating a table from a select query.
 * Returns: query value.
 */
inline auto create_table_as_select() {
    using namespace sqlgen::literals;

    return sqlgen::create_as<Target>(
        sqlgen::select_from<Source>("value"_c) 
        | sqlgen::where("value"_c > 100)
    );
}

}  // namespace create_table_as_select
```

**Explanation:**

1. **Using literals**: The `sqlgen::literals` namespace provides the `_c` literal suffix to create column references conveniently.

2. **Select query**: `sqlgen::select_from<Source>("value"_c)` creates a SELECT query that selects the `value` column from the `Source` table.

3. **Where clause**: The pipe operator `|` chains the `where("value"_c > 100)` condition to filter only records where the value is greater than 100.

4. **Create table as select**: `sqlgen::create_as<Target>(...)` wraps the select query to create a CREATE TABLE AS SELECT statement that will create the `Target` table with the results.

5. **Return value**: The function returns the query object which can later be executed on a database connection or converted to SQL using `to_sql()`.

